func canWin(s string) bool {
	b := []byte(s)
	var win func() bool
	win = func() bool {
		for i := 1; i < len(b); i++ {
			if b[i] == '+' && b[i-1] == '+' {
				b[i], b[i-1] = '-', '-'
				ok := !win()
				b[i], b[i-1] = '+', '+'
				if ok {
					return true
				}
			}
		}
		return false
	}
	return win()
}

class Solution {
  public boolean canWin(String s) {
    char[] b = s.toCharArray();
    return win(b);
  }

  private boolean win(char[] b) {
    for (int i = 1; i < b.length; i++) {
      if (b[i] == '+' && b[i - 1] == '+') {
        b[i] = b[i - 1] = '-';
        boolean ok = !win(b);
        b[i] = b[i - 1] = '+';
        if (ok) {
          return true;
        }
      }
    }
    return false;
  }
}

class Solution:
    def canWin(self, s: str) -> bool:
        for i in range(1, len(s)):
            if s[i] == "+" and s[i - 1] == "+":
                if not self.canWin(s[:i - 1] + "--" + s[i + 1:]):
                    return True
        return False

impl Solution {
  pub fn can_win(s: String) -> bool {
    let mut b: Vec<u8> = s.into_bytes();
    Solution::win(&mut b)
  }

  fn win(b: &mut Vec<u8>) -> bool {
    for i in 1..b.len() {
      if b[i] == b'+' && b[i - 1] == b'+' {
        b[i] = b'-';
        b[i - 1] = b'-';
        let ok = !Solution::win(b);
        b[i] = b'+';
        b[i - 1] = b'+';
        if ok {
          return true;
        }
      }
    }
    false
  }
}

const canWin = (s: string): boolean => {
  for (let i = 1; i < s.length; i++) {
    if (s[i] === '+' && s[i - 1] === '+') {
      if (!canWin(s.slice(0, i - 1) + '--' + s.slice(i + 1))) return true;
    }
  }
  return false;
};

class Solution {
private:
  map<string, bool> memo;

public:
  bool canWin(string s) {
    if (memo.count(s)) return memo[s];
    for (int i = 1; i < s.size(); ++i) {
      if (s[i] == '+' && s[i - 1] == '+') {
        string t = s;
        t[i] = t[i - 1] = '-';
        if (!canWin(t)) {
          memo[s] = true;
          return true;
        }
      }
    }
    memo[s] = false;
    return memo[s];
  }
};
